import { cn, fileKind, type FileKind } from '@gntik-ai/ui';
import { AlertCircle, File, FileArchive, FileAudio, FileCode, FileImage, FileSpreadsheet, FileText, FileVideo, RotateCcw, X, type LucideIcon } from 'lucide-react';
import type { Ref } from 'react';
import { formatBytes } from '../utils/format';
import { useChatI18n } from '../utils/i18n';
import { attachmentStyles as s } from './attachment.variants';

/** A file attached to a message or waiting in the composer. */
export interface ChatAttachment {
  id: string;
  name: string;
  /** Size in bytes. */
  size?: number;
  /** MIME type; picks the icon (falls back to the extension). */
  type?: string;
  /** Image preview URL (e.g. from URL.createObjectURL); shown as a thumbnail for images. */
  previewUrl?: string;
  /** Upload progress 0–100 (`null` = indeterminate). Omit when not uploading. */
  progress?: number | null;
  /** Upload failed; a string replaces the default message. */
  error?: boolean | string;
}

export type AttachmentStatus = 'idle' | 'uploading' | 'error';

export interface AttachmentChipProps {
  attachment: ChatAttachment;
  /** `chip` (composer, compact row) or `tile` (message, larger image preview). */
  variant?: 'chip' | 'tile';
  /** Shows the remove button. */
  onRemove?: (id: string) => void;
  /** Shows a retry button in the error state. */
  onRetry?: (id: string) => void;
  disabled?: boolean;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

const ICONS: Record<FileKind, LucideIcon> = {
  image: FileImage,
  video: FileVideo,
  audio: FileAudio,
  archive: FileArchive,
  code: FileCode,
  spreadsheet: FileSpreadsheet,
  document: FileText,
  file: File,
};

/** Status of an attachment from its progress and error fields. */
export function attachmentStatus(a: ChatAttachment): AttachmentStatus {
  if (a.error) return 'error';
  if (a.progress === null || (typeof a.progress === 'number' && a.progress < 100)) return 'uploading';
  return 'idle';
}

/**
 * One attached file: image thumbnail or file-type icon, name, size, upload progress
 * (a progressbar), error with retry, and a remove button.
 */
export function AttachmentChip({ attachment: a, variant = 'chip', onRemove, onRetry, disabled = false, className, ref }: AttachmentChipProps) {
  const { t, tc } = useChatI18n();
  const status = attachmentStatus(a);
  const kind = fileKind(a.name, a.type);
  const Icon = status === 'error' ? AlertCircle : ICONS[kind];
  const showImage = a.previewUrl !== undefined && kind === 'image' && status !== 'error';
  const tile = variant === 'tile';
  const pct = typeof a.progress === 'number' ? Math.max(0, Math.min(100, Math.round(a.progress))) : null;

  const media = (
    <span className={cn(tile ? s.tileMedia : s.media, status === 'error' && s.mediaError)}>
      {showImage ? <img src={a.previewUrl} alt="" className={s.img} /> : <Icon size={tile ? 22 : 14} aria-hidden />}
    </span>
  );

  const meta =
    status === 'error' ? (
      <span className={s.metaError}>{typeof a.error === 'string' ? a.error : tc('chat.uploadFailed')}</span>
    ) : status === 'uploading' ? (
      <span className={s.meta}>{pct === null ? t('common.loading') : `${pct}%`}</span>
    ) : a.size !== undefined ? (
      <span className={s.meta}>{formatBytes(a.size)}</span>
    ) : null;

  const buttons = (
    <>
      {status === 'error' && onRetry && (
        <button type="button" className={s.button} aria-label={tc('chat.retryUpload', { name: a.name })} disabled={disabled} onClick={() => onRetry(a.id)}>
          <RotateCcw size={12} aria-hidden />
        </button>
      )}
      {onRemove && (
        <button type="button" className={s.button} aria-label={t('common.removeItem', { label: a.name })} disabled={disabled} onClick={() => onRemove(a.id)}>
          <X size={12} aria-hidden />
        </button>
      )}
    </>
  );

  return (
    <div ref={ref} data-status={status} data-kind={kind} className={cn(tile ? s.tile : s.chip, className)}>
      {media}
      <span className={tile ? s.tileText : s.text}>
        <span className={s.name} title={a.name}>
          {a.name}
        </span>
        {meta}
      </span>
      {tile ? (onRemove || (status === 'error' && onRetry)) && <span className={s.tileActions}>{buttons}</span> : buttons}
      {status === 'uploading' && (
        <span
          role="progressbar"
          aria-label={tc('chat.uploading', { name: a.name })}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={pct ?? undefined}
          className={s.track}
        >
          <span className={pct === null ? s.barIndeterminate : s.bar} style={pct === null ? undefined : { width: `${pct}%` }} />
        </span>
      )}
    </div>
  );
}

import { cn } from '@gntik-ai/ui';
import type { Ref } from 'react';
import { useChatI18n } from '../utils/i18n';
import { AttachmentChip, type ChatAttachment } from './AttachmentChip';
import { attachmentStyles as s } from './attachment.variants';

export interface AttachmentListProps {
  attachments: ChatAttachment[];
  /** `chip` for the composer, `tile` for larger image previews in a message. */
  variant?: 'chip' | 'tile';
  onRemove?: (id: string) => void;
  onRetry?: (id: string) => void;
  disabled?: boolean;
  /** Accessible name of the list. Default "Attachments". */
  label?: string;
  className?: string;
  ref?: Ref<HTMLUListElement>;
}

/** A labelled list of AttachmentChips. Renders nothing when empty. */
export function AttachmentList({ attachments, variant = 'chip', onRemove, onRetry, disabled, label, className, ref }: AttachmentListProps) {
  const { t } = useChatI18n();
  if (attachments.length === 0) return null;
  return (
    <ul ref={ref} aria-label={label ?? t('chat.attachments')} className={cn(s.list, className)}>
      {attachments.map((a) => (
        <li key={a.id} className={s.item}>
          <AttachmentChip attachment={a} variant={variant} onRemove={onRemove} onRetry={onRetry} disabled={disabled} />
        </li>
      ))}
    </ul>
  );
}

export { AttachmentChip, attachmentStatus, type AttachmentChipProps, type ChatAttachment, type AttachmentStatus } from './AttachmentChip';
export { AttachmentList, type AttachmentListProps } from './AttachmentList';
export { matchesAccept, validateFiles, type AttachmentRejection, type AttachmentRejectionReason, type ValidateFilesOptions } from './validateFiles';
export { attachmentStyles } from './attachment.variants';
export { doc as attachmentListDoc } from './Attachment.doc';

export type AttachmentRejectionReason = 'type' | 'size' | 'count';

export interface AttachmentRejection {
  file: File;
  reason: AttachmentRejectionReason;
  /** Human-readable message (set by ChatComposer from the i18n catalog). */
  message: string;
}

export interface ValidateFilesOptions {
  /** Same syntax as `<input accept>`: ".pdf,.csv,image/*,application/json". */
  accept?: string;
  /** Largest allowed file, in bytes. */
  maxSize?: number;
  /** Most files allowed in total, counting `current`. */
  maxFiles?: number;
  /** Files already attached. */
  current?: number;
}

/** Whether a file matches an `accept` list (extensions, exact MIME types and `type/*`). */
export function matchesAccept(file: Pick<File, 'name' | 'type'>, accept?: string): boolean {
  if (!accept?.trim()) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return accept
    .split(',')
    .map((a) => a.trim().toLowerCase())
    .filter(Boolean)
    .some((rule) => {
      if (rule.startsWith('.')) return name.endsWith(rule);
      if (rule.endsWith('/*')) return type.startsWith(rule.slice(0, -1));
      return type === rule;
    });
}

/** Splits files into accepted ones and rejections (without messages) by type, size and count. */
export function validateFiles(files: File[], { accept, maxSize, maxFiles, current = 0 }: ValidateFilesOptions) {
  const accepted: File[] = [];
  const rejected: Array<{ file: File; reason: AttachmentRejectionReason }> = [];
  for (const file of files) {
    if (!matchesAccept(file, accept)) rejected.push({ file, reason: 'type' });
    else if (maxSize !== undefined && file.size > maxSize) rejected.push({ file, reason: 'size' });
    else if (maxFiles !== undefined && current + accepted.length >= maxFiles) rejected.push({ file, reason: 'count' });
    else accepted.push(file);
  }
  return { accepted, rejected };
}

/** "840 ms" below a second, "2.4 s" below a minute, "1 m 05 s" above. */
export function formatDuration(ms: number) {
  if (ms < 1000) return `${Math.round(ms)} ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)} s`;
  const m = Math.floor(ms / 60_000);
  const s = Math.round((ms % 60_000) / 1000);
  return `${m} m ${String(s).padStart(2, '0')} s`;
}

/** "12 KB", "3.4 MB". */
export function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

/** Short local time ("14:05") for a message timestamp. */
export function formatTime(date: Date) {
  return date.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

/** Pretty-prints any value as JSON; falls back to String() for cyclic or exotic values. */
export function toJson(value: unknown) {
  if (typeof value === 'string') return value;
  try {
    return JSON.stringify(value, null, 2) ?? String(value);
  } catch {
    return String(value);
  }
}

import { interpolate, useI18n, type MessageKey, type MessageVars } from '@gntik-ai/ui';

/**
 * English fallbacks for the chat keys added after the first `@gntik-ai/ui` release. The
 * strings live in the ui catalogs (en + es); these keep the pack readable when it runs
 * against an older `@gntik-ai/ui` whose catalog does not have them yet.
 */
const FALLBACK = {
  'chat.typing': '{author} is typing',
  'chat.feedback': 'Response feedback',
  'chat.feedbackTitle': 'What went wrong?',
  'chat.feedbackReason': 'Reason',
  'chat.feedbackComment': 'Comment (optional)',
  'chat.feedbackPlaceholder': 'Tell us more…',
  'chat.feedbackSubmit': 'Send feedback',
  'chat.feedbackThanks': 'Thanks for your feedback',
  'chat.feedbackCleared': 'Feedback removed',
  'chat.reasonInaccurate': 'Inaccurate',
  'chat.reasonUnhelpful': 'Not helpful',
  'chat.reasonIncomplete': 'Incomplete',
  'chat.reasonUnsafe': 'Harmful or unsafe',
  'chat.reasonOther': 'Other',
  'chat.regenerate': 'Regenerate',
  'chat.uploading': 'Uploading {name}',
  'chat.uploadFailed': 'Upload failed',
  'chat.retryUpload': 'Retry uploading {name}',
  'chat.dropFiles': 'Drop files to attach',
  'chat.fileTooLarge': '{name} is larger than {max}',
  'chat.fileTypeNotAllowed': '{name} is not an allowed file type',
  'chat.tooManyFiles': 'You can attach up to {max} files',
  'chat.model': 'Model',
  'chat.selectModel': 'Select a model',
  'chat.capabilityVision': 'Vision',
  'chat.capabilityTools': 'Tools',
  'chat.capabilityReasoning': 'Reasoning',
  'chat.capabilityFiles': 'Files',
  'chat.capabilityWeb': 'Web search',
  'chat.capabilityAudio': 'Audio',
  'chat.contextWindow': '{size} context',
  'chat.unavailable': 'Unavailable',
} as const;

export type ChatMessageKey = keyof typeof FALLBACK;

/** `useI18n()` plus `tc()`, a translator for the newer chat keys with English fallbacks. */
export function useChatI18n() {
  const i18n = useI18n();
  const tc = (key: ChatMessageKey, vars?: MessageVars) => {
    const out = i18n.t(key as MessageKey, vars);
    return out === key ? interpolate(FALLBACK[key], vars, i18n.locale) : out;
  };
  return { ...i18n, tc };
}

import type { ComponentDoc } from '@gntik-ai/ui';

export const doc: ComponentDoc = {
  name: 'AttachmentList',
  group: 'Display',
  status: 'beta',
  description:
    'Files attached to a message or waiting in the composer. Each AttachmentChip shows an image thumbnail or a file-type icon, the name, the size, upload progress (a labelled progressbar; indeterminate holds still under reduced motion), an error with Retry, and a Remove button. `variant="tile"` gives larger image previews inside a message. `validateFiles` / `matchesAccept` back the composer’s accept and max-size checks.',
  pattern: 'list',
  keyboard: [
    ['Tab', 'Moves through each chip’s Retry (on error) and Remove buttons'],
    ['Enter / Space', 'Activates the focused Retry or Remove button'],
  ],
  tokens: ['secondary', 'card', 'border', 'muted-foreground', 'primary', 'destructive', 'destructive-text', 'focus-ring'],
};
